const raw = String($json.metric || 'weight').toLowerCase().trim();
let variants, label, unit;
if (/вес|weight|масс/.test(raw)) { variants = ['вес','weight']; label = 'веса'; unit = 'кг'; }
else if (/тали|waist/.test(raw)) { variants = ['талия','waist']; label = 'талии'; unit = 'см'; }
else if (/жир|fat/.test(raw)) { variants = ['body_fat_pct','% жира','жир','bodyfat']; label = '% жира'; unit = '%'; }
else if (/бедр|hip/.test(raw)) { variants = ['бедра','hip','hips']; label = 'бёдер'; unit = 'см'; }
else { variants = [raw]; label = raw; unit = ''; }
return [{ json: { variants, label, unit, bot_id: $json.bot_id, user_id: Number($json.user_id), chat_id: String($json.chat_id), bot_token: $json.bot_token } }];

const m = $('Метрика').first().json;
let pts = $json.points; if (typeof pts === 'string') { try { pts = JSON.parse(pts); } catch(e){ pts = []; } }
pts = (pts || []).filter(p => p && p.v != null);
if (pts.length < 2) { return [{ json: { enough: false, label: m.label } }]; }
const vals = pts.map(p => Number(p.v));
const dates = pts.map(p => String(p.d));
const minV = Math.min.apply(null, vals), maxV = Math.max.apply(null, vals);
const pad = (maxV - minV) * 0.15 || Math.max(1, maxV*0.02);
const lo = minV - pad, hi = maxV + pad;
const W = 700, H = 400, mL = 64, mR = 30, mT = 64, mB = 52;
const pw = W - mL - mR, ph = H - mT - mB;
const X = i => mL + (pts.length === 1 ? pw/2 : pw * i/(pts.length-1));
const Y = v => mT + ph * (1 - (v - lo)/(hi - lo));
const poly = pts.map((p,i) => X(i).toFixed(1)+','+Y(vals[i]).toFixed(1)).join(' ');
const circles = pts.map((p,i) => '<circle cx="'+X(i).toFixed(1)+'" cy="'+Y(vals[i]).toFixed(1)+'" r="4" fill="#38bdf8"/>').join('');
const last = vals[vals.length-1], first = vals[0];
const diff = Math.round((last - first)*10)/10;
const diffStr = diff === 0 ? 'без изменений' : ((diff>0?'+':'')+diff+' '+m.unit+' за период');
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;');
const ticks = [lo, (lo+hi)/2, hi].map(v => { const yy = Y(v); return '<line x1="'+mL+'" y1="'+yy.toFixed(1)+'" x2="'+(W-mR)+'" y2="'+yy.toFixed(1)+'" stroke="#1e293b" stroke-width="1"/><text x="'+(mL-10)+'" y="'+(yy+4).toFixed(1)+'" fill="#94a3b8" font-size="13" text-anchor="end">'+v.toFixed(1)+'</text>'; }).join('');
const xlab = '<text x="'+mL+'" y="'+(H-mB+24)+'" fill="#94a3b8" font-size="12">'+dates[0]+'</text><text x="'+(W-mR)+'" y="'+(H-mB+24)+'" fill="#94a3b8" font-size="12" text-anchor="end">'+dates[dates.length-1]+'</text>';
const svg = '<svg width="'+W+'" height="'+H+'" xmlns="http://www.w3.org/2000/svg">'
 + '<rect width="'+W+'" height="'+H+'" fill="#0f172a"/>'
 + '<text x="'+mL+'" y="36" fill="#e2e8f0" font-family="sans-serif" font-size="22" font-weight="bold">Динамика '+esc(m.label)+'</text>'
 + '<text x="'+(W-mR)+'" y="36" fill="#38bdf8" font-family="sans-serif" font-size="15" text-anchor="end">'+last+' '+esc(m.unit)+' ('+diffStr+')</text>'
 + ticks
 + '<polyline points="'+poly+'" fill="none" stroke="#38bdf8" stroke-width="3"/>'
 + circles + xlab + '</svg>';
const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><style>html,body{margin:0;padding:0;font-family:sans-serif}</style></head><body>'+svg+'</body></html>';
const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return [{ json: { enough: true, W, H, label: m.label }, binary: { html: bin } }];
